diff --git a/src/auth.ts b/src/auth.ts
index 005c41b..9f6c034 100644
--- a/src/auth.ts
+++ b/src/auth.ts
@@ -12,6 +12,12 @@ export function createSession(userId: string, ttlMs = DEFAULT_TTL_MS): Session {
   return { userId, createdAt: now, expiresAt: now + ttlMs };
 }

+// Returns a new session whose expiry starts from now; the input is not mutated.
+export function refreshSession(session: Session, ttlMs = DEFAULT_TTL_MS): Session {
+  const now = Date.now();
+  return { ...session, expiresAt: now + ttlMs };
+}
+
 export function isExpired(session: Session, now = Date.now()): boolean {
   return now > session.expiresAt;
 }
